{"category_edits":[{"category":"learning_objective","rationale":"Blend 90% of the existing weighted pairwise loss with 10% sampled candidate cross-entropy to encourage candidate competition, reusing the same positive and negative scores without changing sampling or architecture.","edits":[{"find":"    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)
    return (weights * pairwise_loss).sum()","replace":"    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)
    original_loss = (weights * pairwise_loss).sum()
    candidate_logits = torch.stack((valid_pos, valid_neg), dim=-1)
    candidate_ce = (torch.logsumexp(candidate_logits, dim=-1) - valid_pos).mean()
    return 0.9 * original_loss + 0.1 * candidate_ce"}]}],"change_summary":"Changed only the learning objective; preserved GRU architecture, predictor, sampling, optimizer, scheduling, and training settings."}
